SELECT count(*) FROM public.chartevents chartevents
  LEFT JOIN (SELECT DISTINCT d.hadm_id AS key1, d.stay_id AS key2, 1 AS hit FROM (SELECT DISTINCT hadm_id, stay_id FROM public.chartevents) d, public.admissions a, public.patients p, public.icustays i, public.transfers t, public.services s, public.outputevents oe, public.procedures_icd pr WHERE p.subject_id = a.subject_id AND t.hadm_id = a.hadm_id AND t.careunit = i.last_careunit AND s.hadm_id = a.hadm_id AND s.curr_service = 'MED' AND oe.stay_id = i.stay_id AND oe.itemid = 226559 AND pr.hadm_id = a.hadm_id AND d.hadm_id = a.hadm_id AND d.stay_id = i.stay_id) b1 ON chartevents.hadm_id = b1.key1 AND chartevents.stay_id = b1.key2
  LEFT JOIN (SELECT DISTINCT key1, 1 AS hit FROM (SELECT d.hadm_id AS key1 FROM public.diagnoses_icd d, public.d_icd_diagnoses dd WHERE (d.icd_code = 'I10' OR d.icd_code = '4019') AND dd.icd_code = d.icd_code AND dd.icd_version = d.icd_version) x) b2 ON chartevents.hadm_id = b2.key1
WHERE (b2.hit IS NOT NULL AND b1.hit IS NOT NULL);
